def simulate_snake(board_size, snake, food, moves):
    """
    Simulate a Snake game based on given board, snake state, food, and moves.

    Args:
        board_size: Tuple of (width, height)
        snake: List of (x, y) tuples with head first
        food: List of (x, y) tuples, only the first is active
        moves: List of move directions ("UP", "DOWN", "LEFT", "RIGHT")

    Returns:
        Tuple of (final_snake, alive, food_eaten_count)
    """
    width, height = board_size

    # Helper to check if a position is valid on the board
    def is_valid_pos(x, y):
        return 0 <= x < width and 0 <= y < height

    # Get current active food (first item in list, or None)
    def get_active_food():
        return food[0] if food else None

    # Check for collision with snake body (including head position of previous state)
    def has_body_collision(new_head_x, new_head_y, moving):
        current_snake = list(snake)  # copy to not modify in-place
        # Don't count tail if it's about to move away and we're not growing
        if not moving:
            return False
        # Check all body segments including head (excluding position of tail that may move away)
        for i, seg in enumerate(snake):
            # Tail segment: only exclude if not growing and it would move away
            if i == len(snake) - 1 and not moving:
                continue
            if new_head_x, new_head_y == seg:
                return True
        return False

    # Simulate one step of snake movement
    def move_snake(direction, eat_food):
        head_x, head_y = snake[0]

        # Determine new head position based on direction
        if direction == "UP":
            new_head_x, new_head_y = head_x, head_y - 1
        elif direction == "DOWN":
            new_head_x, new_head_y = head_x, head_y + 1
        elif direction == "LEFT":
            new_head_x, new_head_y = head_x - 1, head_y
        elif direction == "RIGHT":
            new_head_x, new_head_y = head_x + 1, head_y

        # Check for out-of-bounds or self-collision
        if not is_valid_pos(new_head_x, new_head_y):
            return None  # Snake died
        if has_body_collision(new_head_x, new_head_y, eat_food):
            return None  # Self-collision (including eating into own tail)

        # Apply movement: head moves to new position, body follows
        # If not growing, remove last segment (tail)
        new_snake = [(new_head_x, new_head_y)] + snake[:-1]

        # If eating food and there's food, grow by keeping tail in place
        if eat_food:
            current_food = get_active_food()
            new_snake.append(current_food)  # Keep current length + 1
            if current_food:
                food.pop(0)  # Remove eaten food
                if food:
                    food.insert(0, food[-1])  # Shift active food to front (not needed but for clarity)

        return new_snake

    alive = True
    food_eaten_count = 0
    moving = False

    current_food_idx = 0

    # Get initial direction from head position and first body segment
    if len(snake) > 1:
        dx = snake[0][0] - snake[1][0]
        dy = snake[0][1] - snake[1][1]

        if dx == 1:
            moving = "RIGHT"
        elif dx == -1:
            moving = "LEFT"
        elif dy == 1:
            moving = "DOWN"
        elif dy == -1:
            moving = "UP"

    # For first move if no established direction
    if not moving and len(moves) > 0:
        if moves[0] in ["LEFT", "RIGHT"]:
            moving = moves[0]
        else:
            moving = "DOWN"

    # Simulate each move
    for move_direction in moves:
        if not alive:
            break

        eat_food = False
        current_food_pos = get_active_food()

        # If there's food, check if head will reach it with this direction
        # But we can only eat food if we actually move into it
        if current_food_pos and move_direction == "UP" and snake[0][1] == current_food_pos[1] + 1:
            eat_food = True
        elif current_food_pos and move_direction == "DOWN" and snake[0][1] == current_food_pos[1] - 1:
            eat_food = True
        elif current_food_pos and move_direction == "LEFT" and snake[0][0] == current_food_pos[0] + 1:
            eat_food = True
        elif current_food_pos and move_direction == "RIGHT" and snake[0][0] == current_food_pos[0] - 1:
            eat_food = True

        # Move the snake (including eating logic)
        new_snake = move_snake(move_direction, eat_food)

        if new_snake is None:  # Snake died
            alive = False
            break
        else:
            snake = new_snake

            # Count food eaten
            if current_food_pos and (current_food_pos[0], current_food_pos[1]) in snake[:]:
                eat_food = True

        if eat_food:
            food_eaten_count += 1
    else:
        alive = True

    return (snake, alive, food_eaten_count)
